INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('852c7c14-8884-4b77-8c65-e27d6d23c724', '方言のじしょを作っています。', 'Saya sedang membuat kamus dialek.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('852c7c14-8884-4b77-8c65-e27d6d23c724', 'ああっもうっ！かれしの方言がうつっちゃってるずら。', 'Berengsek! Dialek pacar saya telah menular ke saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('852c7c14-8884-4b77-8c65-e27d6d23c724', '私の国の東側出身の人達は変わった方言で喋るので、彼らが何を言っているのか全く分かりません。', 'Orang-orang dari bagian timur negara saya menggunakan dialek yang aneh sehingga mereka tidak mungkin memahaminya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5e7688f3-ae65-4d67-95e1-c63e2b87de3e', 'vocabulary', '手作り', '手作り', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Sesuatu yang dibuat dengan tangan berarti buatan tangan!', 'Sesuatu yang dibuat dengan tangan berarti buatan tangan!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
