INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa9aa47f-a751-4eed-8a1f-e4dfb31c555e', 'カメラマンが近づくとカメはにげてしまった。', 'Saat juru kamera mendekatinya, penyu tersebut lari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa9aa47f-a751-4eed-8a1f-e4dfb31c555e', 'おれの女に近づくな！', 'Jangan mendekati pacarku!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa9aa47f-a751-4eed-8a1f-e4dfb31c555e', '私達に今近づいてきているゾンビ、めちゃくちゃ私のタイプなんだけど。', 'Anehnya, zombie yang mendekati kita saat ini sebenarnya adalah tipeku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('71a300c7-ed70-4050-b69d-f14a7c796638', 'vocabulary', '言い方', '言い方', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Cara mengatakan sesuatu adalah cara Anda mengatakannya. Ini bisa jadi aksen Anda atau cara Anda berbicara.', 'Cara mengatakan sesuatu adalah cara Anda mengatakannya. Ini bisa jadi aksen Anda atau cara Anda berbicara.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
