INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('71a300c7-ed70-4050-b69d-f14a7c796638', 'いいかた', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71a300c7-ed70-4050-b69d-f14a7c796638', 'そうは言っても、言い方ってもんがあるだろ！', 'Itu masuk akal, tetapi Anda harus memikirkan cara Anda mengatakan sesuatu!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71a300c7-ed70-4050-b69d-f14a7c796638', 'そうだ、話はかわるんだけど、コウイチのネコって言ばの言い方、めっちゃかわいくない？', 'Oh, maaf karena mengubah topik pembicaraan, tapi tidakkah menurutmu cara Koichi mengucapkan kata kucing itu lucu sekali?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71a300c7-ed70-4050-b69d-f14a7c796638', 'あなたの物の言い方はとても馬鹿です。', 'Caramu mengatakan itu sangat bodoh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c843c0e1-f697-45be-9a90-67c127002649', 'vocabulary', '早口', '早口', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Jika Anda mempunyai mulut yang cepat, kemungkinan besar Anda adalah orang yang cepat bicara, bukan?', 'Jika Anda mempunyai mulut yang cepat, kemungkinan besar Anda adalah orang yang cepat bicara, bukan?') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
