INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c843c0e1-f697-45be-9a90-67c127002649', 'わたしの兄は、とても早口です。', 'Kakak laki-laki saya adalah pembicara yang sangat cepat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c843c0e1-f697-45be-9a90-67c127002649', 'お前のことが一ばん大すきだよって、何でそんなに早口で言ったの？', 'Mengapa kamu mengatakan bahwa kamu paling mencintaiku begitu cepat?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c843c0e1-f697-45be-9a90-67c127002649', 'こんなに早口の赤ん坊なんて見たことないよ。', 'Saya belum pernah melihat bayi yang berbicara secepat ini sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7992b16c-53f1-4be1-9a37-7e4c3526cd92', 'vocabulary', '足りない', '足りない', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda tahu kata 足りる dari Level 4. Kata apa ini? justru sebaliknya (bentuk negatif pada kata kerja adalah ない). Jadi, apa lawan kata dari 足りる (Mencukupkan)? Kebalikannya adalah tidak cukup atau tidak cukup.', 'Anda tahu kata 足りる dari Level 4. Kata apa ini? justru sebaliknya (bentuk negatif pada kata kerja adalah ない). Jadi, apa lawan kata dari 足りる (Mencukupkan)? Kebalikannya adalah tidak cukup atau tidak cukup.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
