INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7992b16c-53f1-4be1-9a37-7e4c3526cd92', 'お金が十円足りないんです。', 'Aku kekurangan sepuluh yen.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7992b16c-53f1-4be1-9a37-7e4c3526cd92', 'もしスペースが足りなければ、べつの用しについきして、それをてんぷしてください。', 'Jika ruang tidak mencukupi, lampirkan lembar terpisah dengan informasi tambahan.') ON CONFLICT DO NOTHING;
