INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aea7f0c9-0731-4902-995d-3cedb9ceed32', 'それについては、近々はっぴょうがあると思いますよ。', 'Saya pikir akan ada pengumuman tentang hal itu segera.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aea7f0c9-0731-4902-995d-3cedb9ceed32', '近々雪がふるはずなので、たくさんつもったらかまくらを作ります。', 'Seharusnya kita akan segera mendapat salju, jadi kalau banyak, aku akan membuat igloo salju.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aea7f0c9-0731-4902-995d-3cedb9ceed32', 'もしタバコを吸い続けるなら、あなたは近々癌を発症するでしょう。', 'Anda akan terkena kanker dalam waktu dekat jika Anda terus merokok.') ON CONFLICT DO NOTHING;
