INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('466e7394-14ed-4417-9b40-5081b575f0c1', 'わたしたち、ちょっと出会うのが早すぎたみたいね。', 'Sepertinya kami bertemu satu sama lain terlalu dini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('466e7394-14ed-4417-9b40-5081b575f0c1', 'きのうの夜、クラブで、れんあいかんじょうぬきでただ楽しみたいっていう男に出会ってさ、ハマっちゃいけないのは分かってるけど、めちゃくちゃタイプだったんだよね。', 'Tadi malam, aku bertemu pria yang mencari kesenangan tanpa pamrih di klub dan aku tahu aku tidak seharusnya menyukainya, tapi dia benar-benar tipeku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('466e7394-14ed-4417-9b40-5081b575f0c1', '「ニコールって、今、付き合っている人いるの？」「ええ。エリックと1年間付き合っているわ。」「そうなんだ！彼とは、どこで出会ったの？」', '"Apakah kamu sedang berkencan dengan seseorang sekarang, Nicole?" "Ya, aku sudah bertemu Eric selama setahun." "Wow, di mana kalian bertemu?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b56a8c95-175d-4f22-9fd4-57f8fc56d9b0', 'vocabulary', '私', '私', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
