INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa5983c4-4a9b-4a0b-8010-0c2737aba61e', '私立のようちえんはクリスマスの日はお休みだよ。', 'Taman kanak-kanak swasta tutup pada Hari Natal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa5983c4-4a9b-4a0b-8010-0c2737aba61e', 'ここを出て、前の通りを左の方へ三つ目の交さ点まで歩くと、その私立病院に着きますよ。', 'Keluar dari sini dan berjalan ke kiri sepanjang jalan sampai Anda tiba di persimpangan ketiga dan Anda akan sampai ke rumah sakit swasta.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa5983c4-4a9b-4a0b-8010-0c2737aba61e', 'コウイチがカフェでこっそり会っていた男の人は、私立探偵だったということが判明しました。', 'Saya mengetahui bahwa pria yang diam-diam ditemui Koichi di kafe adalah seorang detektif swasta.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('43f31045-9b91-4600-bed3-2b61af36d107', 'vocabulary', '私自身', '私自身', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', '"Jika menyangkut orang seperti diriku... alias aku..." Ketika kamu mengatakan ini, kamu sebenarnya mengatakan "secara pribadi" atau "untuk aku".', '"Jika menyangkut orang seperti diriku... alias aku..." Ketika kamu mengatakan ini, kamu sebenarnya mengatakan "secara pribadi" atau "untuk aku".') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
