INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43f31045-9b91-4600-bed3-2b61af36d107', '私自身は、その動物園の問題にはあまり関心がないんです。', 'Secara pribadi, saya tidak peduli dengan masalah kebun binatang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43f31045-9b91-4600-bed3-2b61af36d107', '私自身は、そんなにきょくたんなことじゃなければ、どんな食生活でも良いと思っています。', 'Bagi saya, asalkan tidak terlalu ekstrem, saya rasa diet apa pun boleh-boleh saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43f31045-9b91-4600-bed3-2b61af36d107', 'あなたがもし私自身よりも私のことを知っていると思ったら、 それはとんだ大間違いよ。', 'Kamu salah besar jika kamu pikir kamu mengenalku lebih baik daripada aku mengenal diriku sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8c896604-435f-43ba-8b6e-2e52842cba07', 'vocabulary', '私立大学', '私立大学', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda pernah melihat 私立, yang berarti "swasta", dan Anda pernah melihat 大学, yang berarti "perguruan tinggi" atau "universitas". Jadi, gabungkan keduanya dan Anda memiliki perguruan tinggi swasta/universitas swasta.', 'Anda pernah melihat 私立, yang berarti "swasta", dan Anda pernah melihat 大学, yang berarti "perguruan tinggi" atau "universitas". Jadi, gabungkan keduanya dan Anda memiliki perguruan tinggi swasta/universitas swasta.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
