INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('965a077b-c27e-49a0-8499-08c110015d6d', '私大の授業料は高いもんね。', 'Biaya kuliah swasta memang mahal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('965a077b-c27e-49a0-8499-08c110015d6d', 'とある大阪の私大で英語を教えています。', 'Saya mengajar bahasa Inggris di universitas swasta di Osaka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('965a077b-c27e-49a0-8499-08c110015d6d', 'こないだ言ってた私大の学園祭の件なんだけど、今回は私の事数にいれないで。ごめん。でも悪く思わないでね。時間ができたら連絡するから。', 'Mengenai festival sekolah di universitas swasta yang Anda ceritakan kemarin, bisakah Anda mengabaikan saya kali ini? Maafkan aku, jangan marah padaku. Saya akan menghubungi Anda ketika saya punya waktu luang.') ON CONFLICT DO NOTHING;
