INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cc680f63-748b-4726-a57a-f0b4ce6bb6f3', 'vocabulary', '身', '身', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kanjinya adalah seseorang, tetapi kata-katanya adalah tubuh. Saya kira seseorang adalah tubuh seseorang, jadi setidaknya mereka serupa.', 'Kanjinya adalah seseorang, tetapi kata-katanya adalah tubuh. Saya kira seseorang adalah tubuh seseorang, jadi setidaknya mereka serupa.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
