INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('317abc16-85d4-475e-9a09-230552eb9ff8', '今人気のプログラミング言語は何ですか？', 'Apa bahasa pemrograman yang populer saat ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('317abc16-85d4-475e-9a09-230552eb9ff8', '言語オタクたちが朝まで言語について語りつくすオフ会にさんかしてきました。', 'Saya bergabung dalam pertemuan offline di mana para ahli bahasa berkumpul dan berbicara tentang bahasa sepanjang malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('317abc16-85d4-475e-9a09-230552eb9ff8', '新しいコンピュータ言語の勉強を始めました。', 'Saya mulai mempelajari bahasa komputer baru.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('caa109d7-57f0-444f-b173-30cfea742a26', 'vocabulary', '地上', '地上', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ingat 地下, yang artinya "di bawah tanah". Nah, ini adalah gabungan antara tanah dan di atas, jadi saya yakin Anda bisa menebak bahwa ini berarti di atas tanah. Namun biasanya benda yang berada di atas tanah tidak mengapung (kecuali jika berada di luar angkasa), sehingga benda tersebut benar-benar berada di atas tanah.', 'Ingat 地下, yang artinya "di bawah tanah". Nah, ini adalah gabungan antara tanah dan di atas, jadi saya yakin Anda bisa menebak bahwa ini berarti di atas tanah. Namun biasanya benda yang berada di atas tanah tidak mengapung (kecuali jika berada di luar angkasa), sehingga benda tersebut benar-benar berada di atas tanah.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
