INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0223917c-3053-4d36-a0a9-6602c54ca12a', 'vocabulary', '会', '会', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah versi kata benda dari pertemuan kanji. Jadi itu berarti pertemuan.', 'Ini adalah versi kata benda dari pertemuan kanji. Jadi itu berarti pertemuan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
