INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2f89818d-c3f8-4681-91c1-7630d30f187f', 'きのうはどうして早く学校に行きましたか。', 'Mengapa kamu pergi ke sekolah lebih awal kemarin?') ON CONFLICT DO NOTHING;
