INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('94ab5021-cb31-4615-8501-79221179f936', 'その死は早すぎました。', 'Kematian mereka terlalu cepat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('94ab5021-cb31-4615-8501-79221179f936', '人は死をのがれることはできない…コウイチい外は。', 'Orang tidak bisa lepas dari kematian, kecuali Koichi.') ON CONFLICT DO NOTHING;
