INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2590b80a-5e45-4acf-893f-ce6d2b902f5e', 'vocabulary', '近く', '近く', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah versi kata benda dari kanji dekat. Jadi itu juga berarti dekat, atau di sekitar sesuatu.', 'Ini adalah versi kata benda dari kanji dekat. Jadi itu juga berarti dekat, atau di sekitar sesuatu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
