INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2590b80a-5e45-4acf-893f-ce6d2b902f5e', '今は、学校の近くに、姉とすんでいます。', 'Saat ini saya tinggal bersama saudara perempuan saya di dekat sekolah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2590b80a-5e45-4acf-893f-ce6d2b902f5e', 'あのアイドル、近くで見るとあんまりかわいくないね。', 'Kalau dilihat dari dekat, idola remaja itu nggak cantik sama sekali ya?') ON CONFLICT DO NOTHING;
