INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5ab43d6a-477e-468c-88ff-d4104450be8c', 'わたしは、日本の考古学にきょうみがあります。', 'Saya tertarik dengan arkeologi Jepang.') ON CONFLICT DO NOTHING;
