INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d716860b-fb39-47cc-a0aa-f6456a294cc4', 'vocabulary', '地中', '地中', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Jika Anda berada di tengah tanah, kemungkinan besar Anda berada di bawah tanah. Apakah Anda seorang penganiaya? Itu cukup keren.', 'Jika Anda berada di tengah tanah, kemungkinan besar Anda berada di bawah tanah. Apakah Anda seorang penganiaya? Itu cukup keren.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
