INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('39832552-1b81-4155-8aea-0c5ae3a308b7', 'コウイチが、別の女と歩いているところを見たの。', 'Saya melihat Koichi berjalan dengan gadis yang berbeda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('39832552-1b81-4155-8aea-0c5ae3a308b7', 'それとこれとは話が別だろう。', 'Ini dan itu adalah dua cerita yang berbeda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('39832552-1b81-4155-8aea-0c5ae3a308b7', 'その場合は別として、このやり方で男女を別にするのは通じょうもんだいありません。', 'Selain itu, biasanya tidak masalah jika memisahkan jenis kelamin dengan cara ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e5869fca-50d9-4494-b10b-752becd8fe9c', 'vocabulary', '大体', '大体', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Jika yang Anda lihat hanyalah bagian besar dari suatu benda, maka Anda hanya akan mendapatkan gambaran umum tentang benda tersebut. Anda akan dapat mengatakan bahwa secara umum ini adalah cara tertentu, tetapi itu saja. Anda akan mendapatkan intinya, tapi tidak lebih.', 'Jika yang Anda lihat hanyalah bagian besar dari suatu benda, maka Anda hanya akan mendapatkan gambaran umum tentang benda tersebut. Anda akan dapat mengatakan bahwa secara umum ini adalah cara tertentu, tetapi itu saja. Anda akan mendapatkan intinya, tapi tidak lebih.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
