INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e5869fca-50d9-4494-b10b-752becd8fe9c', '大体あっています。', 'Itu benar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e5869fca-50d9-4494-b10b-752becd8fe9c', '大体同じぐらいのせです。', 'Tinggi badan kami hampir sama.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e5869fca-50d9-4494-b10b-752becd8fe9c', '私は大体6時に起きます。', 'Saya biasanya bangun jam 6 sore.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('25395bac-b32f-4415-8f6f-28afbcbd874d', 'vocabulary', '広げる', '広げる', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('25395bac-b32f-4415-8f6f-28afbcbd874d', 'Untuk Menyebarkan Sesuatu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('25395bac-b32f-4415-8f6f-28afbcbd874d', 'To Unfold Something', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('25395bac-b32f-4415-8f6f-28afbcbd874d', 'To Open Something Up', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('25395bac-b32f-4415-8f6f-28afbcbd874d', 'ひろげる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25395bac-b32f-4415-8f6f-28afbcbd874d', '日本にそのウィルスを広げたのは水だった。', 'Airlah yang menyebarkan virus di Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25395bac-b32f-4415-8f6f-28afbcbd874d', '大人三人でブランケットを広げた。', 'Tiga orang dewasa membuka selimut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25395bac-b32f-4415-8f6f-28afbcbd874d', '中に入ってすぐ本を広げた。', 'Segera setelah saya masuk ke dalam, saya membuka buku itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a1510bc1-9149-488d-97eb-4bda5b6f306a', 'vocabulary', '出身', '出身', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Jalan keluar seseorang memulai adalah asal usulnya, kampung halamannya, atau tempat kelahirannya.', 'Jalan keluar seseorang memulai adalah asal usulnya, kampung halamannya, atau tempat kelahirannya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a1510bc1-9149-488d-97eb-4bda5b6f306a', 'Asal Usul Seseorang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a1510bc1-9149-488d-97eb-4bda5b6f306a', 'One''s Hometown', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a1510bc1-9149-488d-97eb-4bda5b6f306a', 'One''s Birthplace', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a1510bc1-9149-488d-97eb-4bda5b6f306a', 'しゅっしん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a1510bc1-9149-488d-97eb-4bda5b6f306a', 'どこの出身ですか。', 'Asalmu dari mana?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a1510bc1-9149-488d-97eb-4bda5b6f306a', '私たちは二人とも中国出身です。', 'Kami berdua berasal dari Tiongkok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a1510bc1-9149-488d-97eb-4bda5b6f306a', '夕べのパーティーに、同じ出身の人がいました。', 'Di pesta tadi malam, ada seseorang dari kampung halamanku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fa893367-17ae-4940-b7f8-fd600a688f92', 'vocabulary', '出社', '出社', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Jika Anda keluar dari suatu tempat untuk pergi ke perusahaan Anda, itu pergi ke kantor, tiba di kantor, dan berangkat kerja.', 'Jika Anda keluar dari suatu tempat untuk pergi ke perusahaan Anda, itu pergi ke kantor, tiba di kantor, dan berangkat kerja.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fa893367-17ae-4940-b7f8-fd600a688f92', 'Pergi Ke Kantor', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fa893367-17ae-4940-b7f8-fd600a688f92', 'Arriving At The Office', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fa893367-17ae-4940-b7f8-fd600a688f92', 'Coming To Work', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fa893367-17ae-4940-b7f8-fd600a688f92', 'しゅっしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa893367-17ae-4940-b7f8-fd600a688f92', '今日は、八時に出社しました。', 'Hari ini saya tiba di kantor jam 8 malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa893367-17ae-4940-b7f8-fd600a688f92', '出社前って、どんな風にすごしてますか？', 'Bagaimana Anda menghabiskan waktu sebelum berangkat kerja?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa893367-17ae-4940-b7f8-fd600a688f92', 'もう出社しているはずなのに。', 'Tapi mereka seharusnya sudah bekerja sekarang.') ON CONFLICT DO NOTHING;
